import mdx from '@mdx-js/rollup';
import { reactRouter } from '@react-router/dev/vite';
import rehypeExternalLinks from 'rehype-external-links';
import { defineConfig, normalizePath, type Plugin } from 'vite';
import devtoolsJson from 'vite-plugin-devtools-json';
import tsconfigPaths from 'vite-tsconfig-paths';
import path from 'path';
import { databaseThumbs } from './scripts/thumbs';

function relativeSourcemaps(): Plugin {
  const root = process.cwd();
  return {
    name: 'relative-sourcemaps',
    transform(code, _id) {
      // Only process files with sourcemaps
      if (!code.includes('//# sourceMappingURL=data:')) {
        return null;
      }

      // Extract and modify the inline sourcemap
      const match = code.match(/\/\/# sourceMappingURL=data:application\/json;base64,(.+)$/);
      if (!match) return null;

      try {
        const sourcemap = JSON.parse(Buffer.from(match[1], 'base64').toString());
        if (sourcemap.sources) {
          sourcemap.sources = sourcemap.sources.map((source: string) => {
            // Remove file:// prefix and make relative
            const cleanPath = source.replace(/^file:\/\/\//, '').replace(/^\//, '');
            if (path.isAbsolute(cleanPath)) {
              return path.relative(root, cleanPath);
            }
            return source;
          });
        }
        const newSourcemap = Buffer.from(JSON.stringify(sourcemap)).toString('base64');
        return code.replace(
          match[0],
          `//# sourceMappingURL=data:application/json;base64,${newSourcemap}`
        );
      } catch {
        return null;
      }
    },
  };
}

/**
 * Keep the dev server's file watcher out of directories that are never part
 * of the module graph.
 *
 * Vite watches every file under the project root one by one, and React
 * Router's child compiler (a second Vite server) watches them all again.
 * With a build in place that is about 6,700 watchers, each one a blocking
 * call on Windows: the first page of a cold dev server took 7 s on a quiet
 * machine and two minutes on a busy one, past Vite's own 60 s module-runner
 * timeout and Playwright's 60 s wait for the server.
 *
 * - build/: generated output, 2,000+ files
 * - database/: read with fs on each request (app/lib/data.ts), never
 *   imported, so a YAML edit shows up on refresh with or without a watcher
 * - playwright-report/: generated by the e2e runs
 *
 * This is a plugin rather than `server.watch` below because the child
 * compiler takes the config file's plugins but replaces its `server` block.
 */
function quietWatcher(): Plugin {
  const dir = (name: string) => `${normalizePath(path.resolve(__dirname, name))}/**`;
  return {
    name: 'quiet-watcher',
    config(_config, { command }) {
      // A build has no watcher; returning options here would switch one on
      if (command !== 'serve') return;
      return {
        server: {
          watch: { ignored: [dir('build'), dir('database'), dir('playwright-report')] },
        },
      };
    },
  };
}

export default defineConfig({
  plugins: [
    mdx({
      rehypePlugins: [[rehypeExternalLinks, { target: '_blank', rel: ['noopener', 'noreferrer'] }]],
    }),
    reactRouter(),
    tsconfigPaths(),
    devtoolsJson(),
    relativeSourcemaps(),
    databaseThumbs(),
    quietWatcher(),
  ],
  resolve: {
    alias: {
      '~': path.resolve(__dirname, './app'),
    },
  },
  css: {
    devSourcemap: true,
  },
  build: {
    sourcemap: true,
    rollupOptions: {
      output: {
        sourcemapPathTransform: (relativeSourcePath, sourcemapPath) => {
          // Make paths relative to the repo root
          const absolutePath = path.resolve(path.dirname(sourcemapPath), relativeSourcePath);
          return path.relative(process.cwd(), absolutePath);
        },
      },
    },
  },
});
